"""Toy encrypted aggregation example for federated learning."""

from phe import generate_paillier_keypair


def encrypted_mean(values):
    public_key, private_key = generate_paillier_keypair(n_length=512)
    encrypted_sum = sum(public_key.encrypt(value) for value in values)
    return private_key.decrypt(encrypted_sum / len(values))


def main():
    local_updates = [0.45, 0.52, 0.49, 0.54]
    secure_average = encrypted_mean(local_updates)
    print("local updates:", local_updates)
    print("secure average:", secure_average)


if __name__ == "__main__":
    main()

