"""Toy encrypted score aggregation for a logistic model."""

import math

from phe import generate_paillier_keypair


def sigmoid(x):
    return 1.0 / (1.0 + math.exp(-x))


def encrypted_linear_score(weights, features):
    public_key, private_key = generate_paillier_keypair(n_length=512)
    encrypted_terms = [public_key.encrypt(x) * w for w, x in zip(weights, features)]
    encrypted_score = sum(encrypted_terms)
    return private_key.decrypt(encrypted_score)


def main():
    weights = [0.9, -0.4, 1.2]
    features = [1.0, 0.25, -0.5]
    linear_score = encrypted_linear_score(weights, features)
    probability = sigmoid(linear_score)
    print("linear score:", linear_score)
    print("probability:", probability)


if __name__ == "__main__":
    main()

